var i=187;var a=`187-dividing-pre-shaping-and-final-shaping`;var n=`178`;var s={en:`Dividing, Pre-Shaping, and Final Shaping`,ua:`Поділ, попереднє та остаточне формування тіста`};var r={short:`Dividing, pre-shaping, resting and final shaping turn fermented dough into consistent loaves. The sequence controls portion mass, gas retention and surface tension for a predictable bake.`,sections:[{title:`Core idea`,text:`After bulk fermentation, divide according to target dough weight. Pre-shape gently, rest to relax, then finish as a round boule, long bâtard, sandwich loaf or rolls; seal seams and position them according to the baking method.`},{title:`Scientific / practical principles`,text:`Outer tension supports gas cells as the dough expands, but a skin that is too tight can tear. Rest between pre-shaping and shaping reduces elastic recoil; excessive degassing makes the crumb unusually tight.`},{title:`How to apply it`,text:`Use a scale for every piece; lightly flour hands and bench instead of burying the dough in flour. Form a taut but unbroken surface and place the seam correctly in the basket or pan.`},{title:`Practical example`,text:`Divide 900 g dough into three 300 g rolls or loaves; compare their proofing and baking with three uneven pieces cut by eye.`},{title:`Common mistakes and limitations`,text:`Overflouring prevents seams from sealing; rough cutting tears gas structures. Shape only after sufficient bulk fermentation, or tension will not rescue weakly fermented dough.`},{title:`Additional insight`,text:`A gentle pre-shape followed by a covered bench rest lets the dough relax before final shaping. Too much degassing removes useful gas cells; too little surface tension allows a shaped loaf to spread.`},{title:`Related theories`,text:`181, 185, 188, 189.`}]};var o={short:`Поділ, попереднє формування, відпочинок та остаточне формування перетворюють виброджене тісто на однакові заготовки. Ця послідовність контролює масу, збереження газу й натяг поверхні для передбачуваного випікання.`,sections:[{title:`Суть`,text:`Після першого бродіння поділіть тісто за заданою масою. Легко округліть заготовки, дайте їм розслабитися й сформуйте кулю, подовжений хліб, формовий буханець або булочки. Добре закрийте шви.`},{title:`Наукові та практичні принципи`,text:`Натяг зовнішнього шару допомагає утримати газ під час росту, але занадто туга поверхня тріскається. Відпочинок між попереднім і фінальним формуванням зменшує зворотне стягування; сильне сплющення руйнує пористість.`},{title:`Як застосовувати`,text:`Зважуйте кожну заготовку, підпилюйте стіл помірно. Створюйте гладку натягнуту поверхню без розривів; кладіть заготовку швом униз або вгору відповідно до кошика чи форми.`},{title:`Практичний приклад`,text:`Поділіть 900 г тіста на три заготовки по 300 г і порівняйте їхнє вистоювання з трьома заготовками, відміряними «на око».`},{title:`Поширені помилки й обмеження`,text:`Надлишок борошна заважає закривати шви, а грубий поділ руйнує газові пори. Саме формування не виправить недостатнє бродіння.`},{title:`Додатковий аспект`,text:`Легке попереднє формування та відпочинок на столі під накриттям розслаблюють тісто перед остаточним формуванням. Надмірне випускання газу зменшує пористість, а слабкий натяг поверхні спричиняє розтікання заготовки.`},{title:`Пов’язані теорії`,text:`181, 185, 188, 189.`}]};var l=[181,185,188,189];var g=`References / Джерела`;var h=[`https://www.kingarthurbaking.com/blog/2023/08/31/proofing-bread`,`https://www.kingarthurbaking.com/blog/2023/12/07/visual-guide-bread-baking`,`https://www.kingarthurbaking.com/learn/bread`,`https://www.kingarthurbaking.com/learn/guides/yeast-baking`,`https://www.kingarthurbaking.com/blog/2019/07/22/bulk-fermentation`];var u={id:187,slug:a,group:`178`,title:s,en:r,ua:o,related:l,referenceTitle:g,references:h};export{u as default,r as en,n as group,i as id,g as referenceTitle,h as references,l as related,a as slug,s as title,o as ua};